import { useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import { useAuth } from "@/context/AuthContext";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Button } from "@/components/ui/button";
import { toast } from "sonner";

export default function Signup() {
  const [f, setF] = useState({ name: "", email: "", phone: "", address: "", city: "Bangalore", state: "KA", pincode: "", password: "", confirm: "" });
  const { register } = useAuth();
  const nav = useNavigate();
  const [loading, setLoading] = useState(false);
  const [devToken, setDevToken] = useState("");

  const submit = async (e) => {
    e.preventDefault();
    if (f.password !== f.confirm) { toast.error("Passwords don't match"); return; }
    setLoading(true);
    const { confirm, ...payload } = f;
    const r = await register(payload);
    setLoading(false);
    if (r.ok) {
      if (r.verify_token) setDevToken(r.verify_token);
      else nav("/login");
    }
  };

  if (devToken) return (
    <div className="max-w-md mx-auto px-4 py-14 text-center" data-testid="verify-notice">
      <h1 className="font-display text-3xl font-bold">Check your inbox</h1>
      <p className="text-[#5C4A3D] mt-2">We've sent a verification link to <b>{f.email}</b>.</p>
      <p className="text-xs text-[#5C4A3D] mt-4">Dev-mode: use this token to verify manually.</p>
      <Link to={`/verify-email?token=${devToken}`} className="btn-primary inline-block mt-4 rounded-full px-6 py-2.5 text-sm uppercase-tracked" data-testid="dev-verify-link">Verify Now</Link>
    </div>
  );

  return (
    <div className="max-w-lg mx-auto px-4 py-14" data-testid="signup-page">
      <h1 className="font-display text-3xl font-bold text-center">Create Account</h1>
      <p className="text-center text-[#5C4A3D] text-sm mt-1">Join SLV Bakery family</p>
      <form onSubmit={submit} className="bg-white border border-[#E6DFD5] rounded-2xl p-6 card-shadow space-y-4 mt-6">
        <div className="grid md:grid-cols-2 gap-3">
          <div><Label>Full Name</Label><Input value={f.name} onChange={(e) => setF({...f, name: e.target.value})} required data-testid="signup-name" /></div>
          <div><Label>Email</Label><Input type="email" value={f.email} onChange={(e) => setF({...f, email: e.target.value})} required data-testid="signup-email" /></div>
          <div><Label>Phone</Label><Input value={f.phone} onChange={(e) => setF({...f, phone: e.target.value})} required /></div>
          <div><Label>Pincode</Label><Input value={f.pincode} onChange={(e) => setF({...f, pincode: e.target.value})} required /></div>
        </div>
        <div><Label>Address</Label><Input value={f.address} onChange={(e) => setF({...f, address: e.target.value})} required /></div>
        <div className="grid md:grid-cols-2 gap-3">
          <div><Label>City</Label><Input value={f.city} onChange={(e) => setF({...f, city: e.target.value})} required /></div>
          <div><Label>State</Label><Input value={f.state} onChange={(e) => setF({...f, state: e.target.value})} required /></div>
        </div>
        <div className="grid md:grid-cols-2 gap-3">
          <div><Label>Password</Label><Input type="password" value={f.password} onChange={(e) => setF({...f, password: e.target.value})} required data-testid="signup-password" /></div>
          <div><Label>Confirm Password</Label><Input type="password" value={f.confirm} onChange={(e) => setF({...f, confirm: e.target.value})} required /></div>
        </div>
        <Button type="submit" disabled={loading} className="btn-primary rounded-full w-full" data-testid="signup-submit">{loading ? "Creating..." : "Create Account"}</Button>
        <div className="text-center text-sm text-[#5C4A3D]">
          Already have an account? <Link to="/login" className="text-[#D97706] font-semibold">Login</Link>
        </div>
      </form>
    </div>
  );
}
